===== fixtures/archive_a/dftb_in.hsd =====
Geometry = genFormat {
 <<< "struc.gen"
}

Driver {}

Hamiltonian = DFTB {
  Solvation = Cosmo {
    Solvent = fromConstants { # Toluene
      Epsilon = 7.0
      MolecularMass [amu] = 92.14
      Density [kg/l] = 0.867
    }
    State = "mol1bar"
    RadiiScaling = 1.35
    AngularGrid = 146
    Solver = DomainDecomposition {
      MaxMoment = 7
      Accuracy = 1e-10
    }
    SASA {
      ProbeRadius [AA] = 1.45
      Smoothing [AA] = 0.25
      Offset [AA] = 1.6
      AngularGrid = 110
      Radii = vanDerWaalsRadiiD3 {}
      SurfaceTension = Values {
        H = -0.80
        O =  0.35
      }
    }
  }
  SCC = Yes
  SccTolerance = 1e-8
  MaxAngularMomentum {
    H = "s"
    O = "p"
  }
  SlaterKosterFiles = Type2FileNames {
    Prefix = {../params/mio-1-1/}
    Separator = "-"
    Suffix = ".skf"
  }
  HubbardDerivs {
     H = -0.1857
     O = -0.1575
  }
  ThirdOrderFull = Yes
  HCorrection = Damping { Exponent = 4.0 }
}

ParserOptions {
  ParserVersion = 8
}

Parallel {
  UseOmpThreads = No
}


